{"version":1,"taskId":"43c7c329-b516-4138-aff1-6143c3895c5b","commandId":"write-types","operation":"run","headSha":"39e05ff6bd2ffe0fb005bb3ce122a544423e3034","timeoutSeconds":300,"command":"cat > src/courses/types.ts <<'EOF'
import type { Quat, Vec3 } from '../contracts/math';

export interface TransformDescriptor {
  position: Vec3;
  rotation?: Quat;
  scale?: Vec3;
}

export type SurfaceMaterial = 'green' | 'rough' | 'sand' | 'ice' | 'wood' | 'stone' | 'metal';

export interface SurfaceDescriptor {
  id: string;
  transform: TransformDescriptor;
  shape: 'box' | 'ramp' | 'cylinder' | 'mesh';
  size: Vec3;
  material: SurfaceMaterial;
  friction?: number;
  restitution?: number;
}

export interface ObstacleBase {
  id: string;
  transform: TransformDescriptor;
  /** Full extents of the box footprint; force obstacles and zones use it as their trigger volume. */
  size: Vec3;
  enabled?: boolean;
}

export interface StaticObstacle extends ObstacleBase {
  type: 'wall' | 'bumper' | 'pillar' | 'block';
  restitution?: number;
}

export interface MotionDescriptor {
  kind: 'rotate' | 'translate' | 'swing';
  axis: Vec3;
  speed: number;
  /** translate only: travel length of one leg. */
  distance?: number;
  phase?: number;
  /** translate only: behaviour at the far end, defaults to ping-pong. */
  loop?: 'ping-pong' | 'loop' | 'once';
  /** translate only: hold time at both ends. */
  pauseSeconds?: number;
  /** rotate/swing only: pivot to arm tip, defaults to half the footprint. */
  armLength?: number;
  /** swing only: half of the pendulum arc in radians. */
  swingAngle?: number;
  /** rotate only: flip the spin direction without touching the speed sign. */
  clockwise?: boolean;
}

export interface MovingObstacle extends ObstacleBase {
  type: 'spinner' | 'windmill' | 'gate' | 'platform' | 'sliding-wall' | 'door' | 'pendulum';
  motion: MotionDescriptor;
}

export interface TeleporterDescriptor extends ObstacleBase {
  type: 'teleporter';
  /** Where the ball reappears after it enters the volume. */
  exit: Vec3;
  exitVelocityScale?: number;
  clearAngularVelocity?: boolean;
}

export interface FanDescriptor extends ObstacleBase {
  type: 'fan';
  direction: Vec3;
  /** Peak acceleration in the middle of the volume. */
  strength: number;
  /** Fade the force out towards the border, defaults to true. */
  falloff?: boolean;
  pulse?: { period: number; minMultiplier: number };
}

export interface ConveyorDescriptor extends ObstacleBase {
  type: 'conveyor';
  direction: Vec3;
  /** Belt speed the ball is dragged towards. */
  strength: number;
  coupling?: number;
}

export type ForceObstacle = TeleporterDescriptor | FanDescriptor | ConveyorDescriptor;

export interface PadDescriptor extends ObstacleBase {
  type: 'spring-pad' | 'boost-pad' | 'jump-pad';
  strength: number;
  /** Defaults to straight up; jump pads ignore it. */
  direction?: Vec3;
  maxSpeed?: number;
  cooldownSeconds?: number;
}

export interface FieldObstacle extends ObstacleBase {
  type: 'gravity-zone' | 'magnet-zone';
  strength: number;
  /** gravity-zone only, defaults to straight down. */
  direction?: Vec3;
  /** magnet-zone only: push away from the center instead of pulling in. */
  repel?: boolean;
}

export interface HazardObstacle extends ObstacleBase {
  type: 'water' | 'void' | 'reset-zone' | 'lava';
  penaltyStrokes?: number;
  /** Explicit respawn point; without it the ball returns to its last safe position. */
  resetPosition?: Vec3;
}

export type ObstacleDescriptor =
  | StaticObstacle
  | MovingObstacle
  | ForceObstacle
  | PadDescriptor
  | FieldObstacle
  | HazardObstacle;

export interface Hole {
  id: string;
  name: string;
  par: number;
  spawn: Vec3;
  cup: { position: Vec3; radius: number; captureDepth: number };
  bounds: { min: Vec3; max: Vec3 };
  surfaces: SurfaceDescriptor[];
  obstacles: ObstacleDescriptor[];
}

export interface Course {
  id: string;
  name: string;
  themeId: string;
  version: number;
  holes: Hole[];
}
EOF
